// Validar y normalizar una lectura MQTT (contrato: contratos/lectura.schema.json).
// Entrada : msg.topic, msg.payload (objeto JSON ya parseado por el nodo mqtt-in).
// Salida 1: msg.lectura = {ts (ms epoch), camara, nodo, variable, valor}  → lectura válida
// Salida 2: {payload:{motivo, topic}}                                    → lectura descartada
const VARIABLES = {
    temp_aire:      { min: 0, max: 120, unidad: '°C' },
    hr_aire:        { min: 0, max: 100, unidad: '%' },
    humedad_madera: { min: 0, max: 100, unidad: '%' },
};

function descartar(motivo) {
    const n = (flow.get('descartadas') || 0) + 1;
    flow.set('descartadas', n);
    if (n === 1 || n % 100 === 0) {
        node.warn(`Lectura descartada (${n} en total): ${motivo} — topic=${msg.topic}`);
    }
    return [null, { payload: { motivo, topic: msg.topic } }];
}

const p = msg.payload;
if (p === null || typeof p !== 'object' || Array.isArray(p)) return descartar('payload no es un objeto JSON');

const claves = ['ts', 'camara', 'nodo', 'variable', 'valor', 'unidad'];
for (const k of claves) {
    if (!(k in p)) return descartar(`falta el campo "${k}"`);
}
if (typeof p.camara !== 'string' || !/^c[0-9]{2}$/.test(p.camara)) return descartar('camara inválida');
if (typeof p.nodo !== 'string' || !/^n[0-9]{2}$/.test(p.nodo)) return descartar('nodo inválido');

const def = VARIABLES[p.variable];
if (!def) return descartar(`variable desconocida: ${p.variable}`);
if (p.unidad !== def.unidad) return descartar(`unidad inválida para ${p.variable}: ${p.unidad}`);

if (typeof p.valor !== 'number' || !Number.isFinite(p.valor)) return descartar('valor no numérico');
if (p.valor < def.min || p.valor > def.max) {
    return descartar(`valor fuera de rango para ${p.variable}: ${p.valor} (válido ${def.min}–${def.max})`);
}

const ts = typeof p.ts === 'string' ? Date.parse(p.ts) : NaN;
if (Number.isNaN(ts)) return descartar('ts inválido');

if (msg.topic !== `secadero/${p.camara}/${p.nodo}/${p.variable}`) {
    return descartar('el topic no coincide con el payload');
}

msg.lectura = { ts, camara: p.camara, nodo: p.nodo, variable: p.variable, valor: p.valor };
return [msg, null];

// Asignar el lote activo de la cámara. El lote se cachea 30 s para no consultar la base en cada mensaje.
// Salida 1: lote en caché → sigue el flujo (msg.lote).
// Salida 2: sin caché      → va a la consulta SQL (msg.query / msg.params).
const TTL_MS = 30000;
const cache = flow.get('lotes') || {};
const c = cache[msg.lectura.camara];
if (c && Date.now() - c.cargado < TTL_MS) {
    msg.lote = c.lote;
    return [msg, null];
}
msg.query = 'SELECT l.id, l.lote, l.especie, l.humedad_inicial, l.humedad_objetivo, l.k_esperada, ' +
            '(SELECT min(ts) FROM lecturas WHERE lote_id = l.id) AS t0 ' +
            'FROM lotes l WHERE l.camara = $1 AND l.fecha_fin IS NULL';
msg.params = [msg.lectura.camara];
return [null, msg];

// Recibe el resultado de la consulta del lote activo y lo guarda en caché.
// Si la cámara no tiene lote activo la lectura se descarta (se avisa, sin inundar el log).
const filas = msg.payload;
if (!Array.isArray(filas) || filas.length === 0) {
    const n = (flow.get('sin_lote') || 0) + 1;
    flow.set('sin_lote', n);
    if (n === 1 || n % 100 === 0) {
        node.warn(`La cámara ${msg.lectura.camara} no tiene lote activo; lectura descartada (${n}). ` +
                  `Crear uno con: SELECT nuevo_lote('${msg.lectura.camara}', 'L-XXXX', 'pino');`);
    }
    return null;
}
const r = filas[0];
const lote = {
    id: r.id,
    nombre: r.lote,
    especie: r.especie,
    hIni: Number(r.humedad_inicial),
    hObj: Number(r.humedad_objetivo),
    k: Number(r.k_esperada),
    // Instante de referencia de la curva esperada: primera lectura del lote (o esta, si es la primera).
    t0: r.t0 ? new Date(r.t0).getTime() : msg.lectura.ts,
};
const cache = flow.get('lotes') || {};
cache[msg.lectura.camara] = { lote, cargado: Date.now() };
flow.set('lotes', cache);

msg.lote = lote;
delete msg.query;
delete msg.params;
msg.payload = undefined;
return msg;

// Arma el INSERT de la lectura en la tabla lecturas.
const L = msg.lectura;
msg.query = 'INSERT INTO lecturas (ts, lote_id, camara, nodo, variable, valor) VALUES ($1, $2, $3, $4, $5, $6)';
msg.params = [new Date(L.ts).toISOString(), msg.lote.id, L.camara, L.nodo, L.variable, L.valor];
return msg;

// Reglas de alerta (docs/CONTRATO.md §3). Mantiene el estado por cámara en el contexto del nodo.
// Entrada : msg.lectura + msg.lote
// Salida 1: array de alertas {payload:{ts,camara,lote_id,severidad,mensaje}, regla}
const CFG = {
    FRESCO_S: 30,          // una lectura sirve para comparar nodos si es de los últimos 30 s
    COOLDOWN_S: 60,        // no repetir la misma alerta antes de 60 s (salvo que escale a roja)
    REPETICIONES: 10,      // valores idénticos seguidos → dato sospechoso
    MIN_NODOS: 3,          // mínimo de nodos con dato fresco para comparar
    DIF_NODOS: 2,          // puntos de humedad entre nodos → amarilla
    DESVIO_AMARILLA: 3,    // puntos contra la curva esperada
    DESVIO_ROJA: 6,
    DESVIO_HR: 15,         // puntos de HR sobre lo esperado → falla de ventilador (roja)
};
const SIM_SPEED = parseFloat(env.get('SIM_SPEED')) || 1;
const RANGO = { amarilla: 1, roja: 2 };

const L = msg.lectura;
const lote = msg.lote;
const estado = context.get('estado') || {};
const cam = estado[L.camara] = estado[L.camara] || { valores: {}, rep: {}, alertas: {} };
context.set('estado', estado);

const salida = [];
function emitir(regla, clave, severidad, mensaje) {
    const previa = cam.alertas[clave];
    const permitido = !previa
        || RANGO[severidad] > RANGO[previa.severidad]
        || (L.ts - previa.ts) >= CFG.COOLDOWN_S * 1000;
    if (!permitido) return;
    cam.alertas[clave] = { severidad, ts: L.ts };
    salida.push({
        regla,
        payload: { ts: new Date(L.ts).toISOString(), camara: L.camara, lote_id: lote.id, severidad, mensaje },
    });
}

// Curva esperada: H(t) = obj + (ini - obj) * exp(-k * SIM_SPEED * t); HR esperada ligada a la humedad.
function esperado() {
    const t = Math.max(0, (L.ts - lote.t0) / 1000);
    const h = lote.hObj + (lote.hIni - lote.hObj) * Math.exp(-lote.k * SIM_SPEED * t);
    const avance = 1 - (h - lote.hObj) / (lote.hIni - lote.hObj);   // 0 → 1
    return { h, hr: 95 - 65 * avance };
}
const f1 = (x) => x.toFixed(1);

// Valores frescos (último de cada nodo) de una variable.
function frescos(variable) {
    const lim = L.ts - CFG.FRESCO_S * 1000;
    const out = [];
    for (const k of Object.keys(cam.valores)) {
        const v = cam.valores[k];
        if (v.variable === variable && v.ts >= lim) out.push(v);
    }
    return out;
}

// 1) Registrar la lectura y detectar valor repetido (dato sospechoso).
const key = `${L.nodo}|${L.variable}`;
cam.valores[key] = { nodo: L.nodo, variable: L.variable, valor: L.valor, ts: L.ts };
const rep = cam.rep[key] = cam.rep[key] || { ultimo: null, n: 0 };
if (rep.ultimo === L.valor) { rep.n += 1; } else { rep.ultimo = L.valor; rep.n = 1; }
if (rep.n >= CFG.REPETICIONES) {
    emitir('dato_sospechoso', `dato_sospechoso|${key}`, 'amarilla',
        `Sensor ${L.nodo}: ${L.variable} repite el valor ${L.valor} en ${rep.n} lecturas seguidas (dato sospechoso)`);
}

// 2) Reglas sobre la humedad de la madera.
if (L.variable === 'humedad_madera') {
    const fs = frescos('humedad_madera');
    if (fs.length >= CFG.MIN_NODOS) {
        let max = fs[0], min = fs[0], suma = 0;
        for (const v of fs) { if (v.valor > max.valor) max = v; if (v.valor < min.valor) min = v; suma += v.valor; }
        const prom = suma / fs.length;

        const dif = max.valor - min.valor;
        if (dif > CFG.DIF_NODOS) {
            emitir('diferencia_nodos', 'diferencia_nodos', 'amarilla',
                `Diferencia de humedad entre nodos: ${f1(dif)} puntos (${max.nodo}=${f1(max.valor)} %, ${min.nodo}=${f1(min.valor)} %)`);
        }

        const esp = esperado();
        const desvio = prom - esp.h;
        const ad = Math.abs(desvio);
        if (ad > CFG.DESVIO_AMARILLA) {
            const sev = ad > CFG.DESVIO_ROJA ? 'roja' : 'amarilla';
            emitir('desvio_curva', 'desvio_curva', sev,
                `Humedad promedio ${f1(prom)} % se desvía ${desvio > 0 ? '+' : ''}${f1(desvio)} puntos de la curva esperada (${f1(esp.h)} %)`);
        }
    }
}

// 3) Falla de ventilador: la humedad del aire sube sobre lo esperado.
if (L.variable === 'hr_aire') {
    const fs = frescos('hr_aire');
    if (fs.length >= CFG.MIN_NODOS) {
        const prom = fs.reduce((a, v) => a + v.valor, 0) / fs.length;
        const esp = esperado();
        if (prom - esp.hr > CFG.DESVIO_HR) {
            emitir('falla_ventilador', 'falla_ventilador', 'roja',
                `Humedad del aire promedio ${f1(prom)} % supera en ${f1(prom - esp.hr)} puntos lo esperado (${f1(esp.hr)} %): posible falla de ventilador`);
        }
    }
}

return salida.length ? [salida] : null;

// Prepara cada alerta para dos destinos:
//   Salida 1: INSERT en la tabla alertas.
//   Salida 2: publicación MQTT en secadero/<camara>/alertas (contratos/alerta.schema.json).
const a = msg.payload;
const sql = {
    query: 'INSERT INTO alertas (ts, lote_id, camara, regla, severidad, mensaje) VALUES ($1, $2, $3, $4, $5, $6)',
    params: [a.ts, a.lote_id, a.camara, msg.regla, a.severidad, a.mensaje],
};
const mqtt = { topic: `secadero/${a.camara}/alertas`, payload: a };
return [sql, mqtt];
